import re

files = [
    'resource/scss/pages/_sub.scss',
    'resource/scss/components/_panel.scss',
    'resource/scss/components/_modal.scss',
    'resource/scss/layouts/_drawer.scss',
    'resource/scss/layouts/_footer.scss',
    'resource/scss/layouts/_header.scss',
    'resource/scss/pages/_works-canvas.scss',
]

def find_duplicates(filepath):
    """Find duplicate CSS properties at same indentation in same block."""
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    duplicates = []
    current_block = None
    block_start = None
    properties_in_block = {}  # {indent_level: {property_name: [(line_no, value)]}}
    indent_stack = []  # Track nesting

    for i, line in enumerate(lines, 1):
        stripped = line.lstrip()
        indent = len(line) - len(stripped)

        # Skip empty lines and comments
        if not stripped or stripped.startswith('//') or stripped.startswith('/*'):
            continue

        # Track opening braces
        if '{' in line:
            indent_stack.append(indent)
            if not current_block:
                current_block = i
                block_start = i
                properties_in_block = {}
            continue

        # Track closing braces
        if '}' in line:
            if indent_stack:
                indent_stack.pop()
            if not indent_stack:
                current_block = None
                properties_in_block = {}
            continue

        # Check for property declaration (property: value;)
        if ':' in line and ';' in line and not line.strip().startswith('$'):
            match = re.match(r'^(\s*)([a-z-]+)\s*:', stripped)
            if match:
                prop_name = match.group(2)
                current_indent = indent

                # Initialize dict for this indent level if needed
                if current_indent not in properties_in_block:
                    properties_in_block[current_indent] = {}

                # Track property
                if prop_name not in properties_in_block[current_indent]:
                    properties_in_block[current_indent][prop_name] = []

                # Extract value (everything after : and before ;)
                value = re.search(r':\s*(.+?);', line)
                if value:
                    properties_in_block[current_indent][prop_name].append((i, value.group(1).strip()))

    # Check for duplicates
    for indent, props in properties_in_block.items():
        for prop_name, occurrences in props.items():
            if len(occurrences) > 1:
                duplicates.append({
                    'property': prop_name,
                    'occurrences': occurrences,
                    'indent': indent
                })

    return duplicates

for filepath in files:
    try:
        dups = find_duplicates(filepath)
        if dups:
            print(f"\n{filepath}:")
            for dup in dups:
                print(f"  Property: {dup['property']}")
                for line_no, value in dup['occurrences']:
                    print(f"    Line {line_no}: {value}")
    except Exception as e:
        print(f"Error in {filepath}: {e}")

