        # Check if this line opens a block
        if '{' in line:
            block_start = i
            # Find closing brace at same or lower indent
            block_lines = [line]
            brace_count = line.count('{') - line.count('}')
            j = i + 1

            while j < len(lines) and brace_count > 0:
                block_lines.append(lines[j])
                brace_count += lines[j].count('{') - lines[j].count('}')
                j += 1

            if brace_count == 0:  # Valid block found
                # Extract properties at same indentation level (skip nested selectors)
                base_indent = len(line) - len(line.lstrip())
                props = {}  # {property_name: [(line_number, line_content, value)]}

                for idx, block_line in enumerate(block_lines[1:-1], start=block_start+1):
                    stripped = block_line.strip()
                    if not stripped or stripped.startswith('//') or stripped.startswith('}'):
                        continue

                    current_indent = len(block_line) - len(block_line.lstrip())

                    # Only interested in properties at immediate child level (base+2 typically)
                    # and only if it's not a selector (doesn't contain &, [, or end with :)
                    if ':' in stripped and ';' in stripped and '{' not in stripped and '&' not in stripped:
                        match = re.match(r'^([a-z-]+)\s*:', stripped)
                        if match:
                            prop_name = match.group(1)
                            value = re.search(r':\s*(.+?);', block_line)
                            if value:
                                value_str = value.group(1).strip()

                                # Track the indent level to see if it matches
                                if prop_name not in props:
                                    props[prop_name] = []
                                props[prop_name].append((idx, block_line.rstrip(), value_str, current_indent))

                # Check for duplicates at same indent
                for prop_name, occurrences in props.items():
                    # Group by indent
                    by_indent = {}
                    for line_num, line_content, value, indent in occurrences:
                        if indent not in by_indent:
                            by_indent[indent] = []
                        by_indent[indent].append((line_num, line_content, value))

                    # If any indent level has 2+ occurrences
                    for indent, occ_list in by_indent.items():
                        if len(occ_list) > 1:
                            selector_line = lines[block_start]
                            duplicates.append({
                                'file': filepath,
                                'selector_line': block_start + 1,
                                'selector': selector_line.rstrip(),
                                'property': prop_name,
                                'occurrences': occ_list,
                                'indent': indent
                            })

                i = j
            else:
                i += 1
        else:
            i += 1

    return duplicates

