import re

def check_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    results = []
    i = 0
    while i < len(lines):
        line = lines[i]
        if '{' in line and not '&' in line:  # Start of simple block
            block_start = i
            block_lines = [line]
            j = i + 1
            brace_count = line.count('{') - line.count('}')

            while j < len(lines) and brace_count > 0:
                block_lines.append(lines[j])
                brace_count += lines[j].count('{') - lines[j].count('}')
                j += 1

            if brace_count == 0 and len(block_lines) > 2:
                # Check content for duplicates
                props_by_indent = {}
                for idx in range(1, len(block_lines)-1):
                    bline = block_lines[idx]
                    stripped = bline.strip()

                    if ':' in stripped and ';' in stripped and not '{' in bline:
                        m = re.match(r'^([a-z-]+)\s*:', stripped)
                        if m:
                            prop = m.group(1)
                            indent = len(bline) - len(bline.lstrip())
                            key = (indent, prop)

                            if key not in props_by_indent:
                                props_by_indent[key] = []
                            props_by_indent[key].append((block_start + idx, bline.rstrip()))

                # Report duplicates
                for (indent, prop), occ in props_by_indent.items():
                    if len(occ) > 1:
                        results.append({
                            'file': filepath,
                            'block_line': block_start + 1,
                            'selector': lines[block_start].strip(),
                            'property': prop,
                            'occurrences': occ
                        })

            i = j
        else:
            i += 1

    return results

